#include<bits/stdc++.h>
#define int long long
using namespace std;
const int N=2*1e5+5;
int n,m,ans=-1e18,s;
int a[N];
bool vis[N];
void dfs(int num,int cnt){
	if(cnt==m){
		ans=max(ans,num);
		return;
	}
	for(int i=1;i<=n;i++){
		if(vis[i]==0){
			vis[i]=1;
			if(cnt==0)dfs(a[i],cnt+1);
			else dfs(num&a[i],cnt+1);
			vis[i]=0;
		}
	}
}
signed main(){
	ios::sync_with_stdio(false);
	cin.tie(0),cout.tie(0);
	freopen("and.in","r",stdin);
	freopen("and.out","w",stdout);
	cin>>n>>m;
	if(m==n){
		cin>>a[1];
		int s=a[1];
		for(int i=2;i<=n;i++){
			cin>>a[i];
			s&=a[i];
		}
		cout<<s;
		return 0;
	}
	else{
		for(int i=1;i<=n;i++){
			cin>>a[i];
		}
//		sort(a+1,a+1+n,greater<int>());
//		int ans=a[2];
//		for(int i=2;i<=m;i++){
//			ans&=a[i];
//		}
	dfs(1,0);
	cout<<ans;
	}
	return 0;
}
